def is_sum_of_two_squares_exact(n):
    if n < _sage_const_0 : return False
    if n == _sage_const_0  or n == _sage_const_1 : return True
    factors = factor(n)
    for p, exp in factors:
        if p % _sage_const_4  == _sage_const_3  and exp % _sage_const_2  != _sage_const_0 :
            return False
    return True

def get_V_all_correct(limit):
    V = {_sage_const_1 }
    for s in range(_sage_const_50 ):
        fs = (_sage_const_10  * _sage_const_16 **s + _sage_const_16  * _sage_const_4 **s + _sage_const_10 ) // _sage_const_9 
        if fs >= limit:
            break
        for i in range(_sage_const_100 ):
            val = fs * _sage_const_4 **i
            if val >= limit:
                break
            V.add(val)
    return sorted(list(V))

primes_pool = [p for p in prime_range(_sage_const_3 , _sage_const_1000 ) if p % _sage_const_4  == _sage_const_3 ]

# Base primes with r mod p (not p^2!)
